<script setup lang="ts">
/**
 * RichTextContent.Inlines: a paragraph’s or a heading’s drawn inlines, each as the element or member of its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { inject } from 'vue'

import {
  richTextPositionAttrs,
  type RichTextDrawnInline,
  type RichTextEntity,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import Code from './Code.vue'
import Link from '../controls/Link.vue'

export interface RichTextContentInlinesProps {
  inlines: RichTextDrawnInline[]
}

defineOptions({ name: 'RichTextContentInlines', inheritAttrs: false })

defineProps<RichTextContentInlinesProps>()
const owner = inject<Record<string, any>>('polymorph:RichTextContent', {})
</script>

<template>
  <template v-for="(node, index) in inlines" :key="index">
    <template v-if="node.kind === 'text'">{{ node.text }}</template>
    <strong v-else-if="node.kind === 'strong'">
      <RichTextContentInlines :inlines="node.children" />
    </strong>
    <em v-else-if="node.kind === 'em'">
      <RichTextContentInlines :inlines="node.children" />
    </em>
    <s v-else-if="node.kind === 's'">
      <RichTextContentInlines :inlines="node.children" />
    </s>
    <!-- highlight -->
    <mark
      v-else-if="node.kind === 'mark'"
      :class="[styles.annotation, owner.pressable ? styles.pressable : undefined]"
      :data-annotation-id="node.id"
      :data-active="node.active ? '' : undefined"
      :role="node.stop ? 'button' : undefined"
      :tabindex="node.stop ? '0' : undefined"
      :aria-current="node.stop && node.active ? 'true' : undefined"
    >
      <RichTextContentInlines :inlines="node.children" />
    </mark>
    <Code v-else-if="node.kind === 'code'">
      {{ node.text }}
    </Code>
    <code v-else-if="node.kind === 'ownCode'" :class="styles.code">
      <RichTextContentInlines :inlines="node.children" />
    </code>
    <Link
      v-else-if="node.kind === 'link' && owner.routes"
      :href="node.href"
      :external="node.external"
      @navigate="(owner.navigate as (href: string) => void)($event)"
    >
      {{ node.text }}
    </Link>
    <Link v-else-if="node.kind === 'link'" :href="node.href" :external="node.external">
      {{ node.text }}
    </Link>
    <br v-else-if="node.kind === 'break'" v-bind="richTextPositionAttrs(node.at, true)" />
    <template v-else-if="node.kind === 'entity' && node.app">
      <component :is="(owner.entityNode as (entity: RichTextEntity) => never)(node.entity)" />
    </template>
    <span
      v-else-if="node.kind === 'entity'"
      :class="styles.entity"
      :data-entity-kind="node.entity.kind"
      :data-entity-id="node.entity.id"
    >
      {{ node.entity.label }}
    </span>
    <span
      v-else-if="node.kind === 'piece'"
      v-bind="richTextPositionAttrs(node.at, node.atom, false)"
    >
      <RichTextContentInlines :inlines="node.children" />
    </span>
  </template>
</template>
